import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { useRef, useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogPanel,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { Spinner } from "@/registry/erbium/ui/spinner";
import { usePredictedIntent } from "@/registry/erbium/hooks/use-predicted-intent";

// The report takes this long to load, as a slow API would.
const loadTime = 900;

type Status = "idle" | "loading" | "ready";

const labels: Record<Status, string> = {
  idle: "not requested",
  loading: "loading",
  ready: "ready",
};

const wait = async (ms: number) => {
  // Browsers have no promise-based timer, so the delay wraps `setTimeout`.
  // oxlint-disable-next-line promise/avoid-new
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

export default function UsePredictedIntentExample() {
  const [status, setStatus] = useState<Status>("idle");
  const [source, setSource] = useState<"click" | "prediction">();
  // The current request; a reset clears it so a late response is ignored.
  const request = useRef<symbol>(undefined);

  // Starts the request once; prediction and opening the dialog share it.
  const load = (trigger: "click" | "prediction") => {
    if (request.current !== undefined) {
      return;
    }

    const current = Symbol(trigger);
    request.current = current;
    setSource(trigger);
    setStatus("loading");
    void (async () => {
      await wait(loadTime);

      if (request.current === current) {
        setStatus("ready");
      }
    })();
  };

  // `load` ignores repeat calls, so prediction can fire again at once after a reset.
  const intentRef = usePredictedIntent(
    () => {
      load("prediction");
    },
    { reactivateAfter: 0 },
  );

  return (
    <div className="flex flex-col items-center gap-group">
      <Dialog
        onOpenChange={(open) => {
          if (open) {
            load("click");
          }
        }}
      >
        <DialogTrigger ref={intentRef} render={<Button variant="outline">Open report</Button>} />
        <DialogPanel className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Quarterly report</DialogTitle>
            <DialogDescription>Revenue and churn for the last quarter.</DialogDescription>
          </DialogHeader>
          <DialogContent>
            {status === "ready" ? (
              <p>Revenue grew 12% while churn held at 2.1%.</p>
            ) : (
              <p className="flex items-center gap-related text-muted-foreground">
                <Spinner /> Loading the report…
              </p>
            )}
          </DialogContent>
        </DialogPanel>
      </Dialog>
      <p className="text-caption text-muted-foreground" aria-live="polite">
        Report data: {labels[status]}
        {source === undefined ? "" : `, requested by ${source}`}.
      </p>
      <Button
        variant="ghost"
        size="sm"
        onClick={() => {
          request.current = undefined;
          setSource(undefined);
          setStatus("idle");
        }}
      >
        Reset
      </Button>
    </div>
  );
}

